class RasaAdapter(Adapter):
    def __init__(self, base_filepath=None, batch_size=10000):# -> None:
        super(RasaAdapter, self).__init__(base_filepath, batch_size)
        self._base_file_contents = None

    @classmethod
    def _get_file_extension(cls):
        return "json"


    def _write_batch(self, output_file_handle, batch):
        rasa_entities = [self.prepare_example(ex) for ex in batch.examples]  # TODO rename this?

        json_data = self._get_base_to_extend()
        json_data["rasa_nlu_data"]["common_examples"] = rasa_entities
        json_data["rasa_nlu_data"]["entity_synonyms"] = \
            self.__format_synonyms(batch.synonyms)
        json_data = cast_to_unicode(json_data)

        output_file_handle.write(
            json.dumps(json_data, ensure_ascii=False, indent=2, sort_keys=True)
        )


    def prepare_example(self, example):
        def entity_to_rasa(entity):
            return {
                "entity": entity.slot_name,
                "value": entity.value,
                "start": entity._start_index,
                "end": entity._start_index + entity._len,
            }

        return {
            "intent": example.intent_name,
            "text": example.text,
            "entities": [entity_to_rasa(entity) for entity in example.entities]
        }

    @classmethod
    def __format_synonyms(cls, synonyms):
        # {str: [str]} -> [{"value": str, "synonyms": [str]}]
        return [
            {
                "value": slot_name,
                "synonyms": synonyms[slot_name]
            }
            for slot_name in synonyms
            if len(synonyms[slot_name]) > 1
        ]


    def _get_base_to_extend(self):
        if self._base_file_contents is None:
            if self._base_filepath is None:
                return self._get_empty_base()
            with io.open(self._base_filepath, 'r') as base_file:
                self._base_file_contents = json.load(base_file)
            self.check_base_file_contents()
        return self._base_file_contents

    def _get_empty_base(self):
        return {
            "rasa_nlu_data": {
                "common_examples": None,
                "regex_features": [],
                "lookup_tables": [],
                "entity_synonyms": None,
            }
        }

    def check_base_file_contents(self):
        """
        Checks that `self._base_file_contents` contains well formatted JSON.
        Throws a `SyntaxError` if the data is incorrect.
        """
        if self._base_file_contents is None:
            return
        if not isinstance(self._base_file_contents, dict):
            self._base_file_contents = None
            raise SyntaxError(
                "Couldn't load valid data from base file '" + \
                self._base_filepath + "'"
            )
        else:
            if "rasa_nlu_data" not in self._base_file_contents:
                self._base_file_contents = None
                raise SyntaxError(
                    "Expected 'rasa_nlu_data' as a root of base file '" + \
                    self._base_filepath + "'")

class RasaMdAdapter(Adapter):
    def __init__(self, base_filepath=None):
        super(RasaMdAdapter, self).__init__(base_filepath, None)
        self._base_file_contents = None


    @classmethod
    def _get_file_extension(cls):
        return "md"
    def __get_file_name(self, batch, output_directory, single_file):
        if single_file:
            return \
                os.path.join(
                    output_directory, "nlu." + self._get_file_extension()
                )
        raise ValueError(
            "Tried to generate several files with Rasa Markdown adapter."
        )


    def _write_batch(self, output_file_handle, batch):
        output_file_handle.write(
            "<!-- Generated using Chatette v" + cast_to_unicode(__version__) + \
            " -->\n\n"
        )

        prepared_examples = dict()
        for example in batch.examples:
            append_to_list_in_dict(
                prepared_examples,
                example.intent_name, self.prepare_example(example)
            )

        for intent_name in prepared_examples:
            output_file_handle.write(
                "## intent:" + cast_to_unicode(intent_name) + '\n'
            )
            for text in prepared_examples[intent_name]:
                output_file_handle.write(cast_to_unicode("- " + text + '\n'))
            output_file_handle.write(cast_to_unicode('\n'))

        output_file_handle.write(
            cast_to_unicode(self.__format_synonyms(batch.synonyms))
        )

        remainder = self._get_base_to_extend()
        if remainder is not None:
            output_file_handle.write(cast_to_unicode(remainder) + '\n')


    def prepare_example(self, example):
        if len(example.entities) == 0:
            return example.text

        sorted_entities = \
            sorted(
                example.entities,
                reverse=True,
                key=lambda entity: entity._start_index
            )
        result = example.text[:]
        for entity in sorted_entities:
            result = \
                result[:entity._start_index] + "[" + \
                result[entity._start_index:entity._start_index + entity._len] + \
                "](" + entity.slot_name + ")" + \
                result[entity._start_index + entity._len:]
        return result


    @classmethod
    def __format_synonyms(cls, synonyms):
        """
        Returns a str that will be written in the output files for all
        the synonyms `synonyms`.
        """
        result = ""
        for syn_name in synonyms:
            if len(synonyms[syn_name]) > 1:
                result += "## synonym:" + syn_name + '\n'
                for syn in synonyms[syn_name]:
                    if syn != syn_name:
                        result += "- " + syn + '\n'
                result += '\n'
        return result


    def _get_base_to_extend(self):
        if self._base_file_contents is None:
            if self._base_filepath is None:
                return self._get_empty_base()
            with io.open(self._base_filepath, 'r') as base_file:
                self._base_file_contents = ''.join(base_file.readlines())
            self.check_base_file_contents()
        return self._base_file_contents

    def _get_empty_base(self):
        return ""

    def check_base_file_contents(self):
        if self._base_file_contents is None:
            return
        if not isinstance(self._base_file_contents, string_types):
            raise SyntaxError(
                "Couldn't load valid data from base file '" + \
                self._base_file_contents + "'"
            )

class JsonListAdapter(Adapter):
    @classmethod
    def _get_file_extension(cls):
        return "jsonl"

    def prepare_example(self, example):
        return json.dumps(
            cast_to_unicode(example.as_dict()),
            ensure_ascii=False, sort_keys=True
        )

    def _write_batch(self, output_file_handle, batch):
        output_file_handle.writelines([
            self.prepare_example(example) + "\n"
            for example in batch.examples
        ])

    def write(self, output_directory, examples, synonyms):
        super(JsonListAdapter, self).write(output_directory, examples, synonyms)

        processed_synonyms = self.__format_synonyms(synonyms)
        if processed_synonyms is not None:
            synonyms_file_path = os.path.join(output_directory, "synonyms.json")
            with io.open(synonyms_file_path, 'w') as output_file:
                output_file.write(
                    json.dumps(
                        cast_to_unicode(processed_synonyms),
                        ensure_ascii=False, sort_keys=True, indent=2
                    )
                )


    @classmethod
    def __format_synonyms(cls, synonyms):
        result = {
            key: values
            for (key, values) in synonyms.items()
            if len(values) > 1 or values[0] != key
        }
        if not result:
            return None
        return result

class Adapter(with_metaclass(ABCMeta, object)):
    """
    Superclass for all the adapters.
    Using the list of generated examples, creates and writes
    the output file(s).
    """
    def __init__(self, base_filepath=None, batch_size=10000):
        super(Adapter, self).__init__()
        self._batch_size = batch_size
        self._base_filepath = base_filepath

    def write(self, output_directory, examples, synonyms):
        """
        Creates files in `output/output_directory` and
        writes batches of the examples `examples` and synonyms `synonyms`
        into them.
        """
        if self._batch_size is not None:
            single_file_output = (len(examples) <= self._batch_size)
        else:
            single_file_output = True

        if not os.path.exists(output_directory):
            os.makedirs(output_directory)

        for batch in self.__generate_batch(examples, synonyms, self._batch_size):
            output_file_path = \
                self.__get_file_name(
                    batch, output_directory, single_file_output
                )
            with io.open(output_file_path, 'w') as output_file:
                self._write_batch(output_file, batch)

    @classmethod
    @abstractmethod
    def _get_file_extension(cls):
        raise NotImplementedError()
    def __get_file_name(self, batch, output_directory, single_file):
        # pylint: disable=bad-continuation
        if single_file:
            return \
                os.path.join(
                    output_directory, "output." + self._get_file_extension()
                )
        return \
            os.path.join(
                output_directory, "output." + str(batch.index) + "." + \
                self._get_file_extension()
            )


    @abstractmethod
    def _write_batch(self, output_file_handle, batch):
        """
        Writes a batch of examples to file `output_file_handle`.
        This file will not be accessed after being written.
        """
        raise NotImplementedError()

    @classmethod
    def __generate_batch(cls, examples, synonyms, nb_examples_per_batch):
        """
        Generates a batch every time it is called, containing
        `nb_examples_per_batch` of the examples `examples`
        and the synonyms `synonyms`.
        If `nb_examples_per_batch` is `None`,
        one batch containing all the examples will be generated.
        """
        if nb_examples_per_batch is None:
            yield Batch(0, examples[:], synonyms)
        else:
            length = len(examples)
            for (batch_index, i) in enumerate(
                range(0, length, nb_examples_per_batch)
            ):
                yield \
                    Batch(
                        batch_index,
                        examples[i:min(i + nb_examples_per_batch, length)],
                        synonyms
                    )


    @abstractmethod
    def prepare_example(self, example):
        """Transforms an example into a str writable to an output file."""
        raise NotImplementedError()

    def _get_base_to_extend(self):
        """
        Returns a representation of the base to extend when writing a file.
        This base is taken from a file given through command line options.
        The type of object returned and what to do with it depends on the
        concrete implementation of the adapter.
        Some adapters shouldn't accept an extendable base.
        """
        raise ValueError(
            self.__class__.__name__ + " does not support base files."
        )
